def whole_hours(total):
    """Return how many complete hours are in total seconds."""
    return total // 3600

def whole_minutes(total):
    """Return the leftover complete minutes once the hours are taken out."""
    return (total % 3600) // 60

def whole_seconds(total):
    """Return the leftover seconds once the hours and minutes are taken out."""
    return total % 60

def duration_text(seconds):
    return str(whole_hours(seconds)) + "h " + str(whole_minutes(seconds)) + "m " + str(whole_seconds(seconds)) + "s"

