def is_free(minutes):
    """Return True when the stay is short enough to cost nothing."""
    return minutes <= 30

def started_hours(minutes):
    """Return how many hours a stay this long has started."""
    return (minutes + 59) // 60

def capped(charge):
    """Return the charge, never above the daily ceiling of 15.00."""
    if charge > 15.0:
        return 15.0
    return charge

def parking_charge(minutes):
    """Return the cost of a stay of this many minutes."""
    if is_free(minutes):
        return 0.0
    return capped(2.5 * started_hours(minutes))

def grade_for(mark):
    """Return the grade letter this mark earns."""
    if mark >= 70:
        return "A"
    if mark >= 60:
        return "B"
    if mark >= 50:
        return "C"
    return "F"

def outcome_for(mark):
    """Return 'pass' or 'fail' for this mark."""
    if mark >= 50:
        return "pass"
    return "fail"

def grade_report(mark):
    """Return the one-line report for this mark."""
    return "Mark " + str(mark) + ": grade " + grade_for(mark) + ", " + outcome_for(mark)

