def base_cost(grams):
    """Return what the parcel costs before any express charge."""
    if grams <= 1000:
        return 3.0
    extra_kilos = (grams - 1000 + 999) // 1000
    return 3.0 + 2.0 * extra_kilos

def shipping_total(grams, express):
    """Return the cost of sending this parcel."""
    cost = base_cost(grams)
    if express:
        return cost * 2
    return cost

